// Concept: the bar writes the name. An accent bar stands up at the foot of the frame first;
// the name slides out from behind it as it is said, as if the bar were drawing it, and the
// role builds beneath it on a band that widens to hold it.
// Storyboard, on the narration's clock:
//   0.0 s  the hook: the accent bar rises from the frame's lower edge at the left of the band
//   0.3 s  "Jane Doe,": the name slides out from behind the bar, clipped at its edge, as it
//          is said
//   1.3 s  "the chief financial officer.": the band widens under the name and the role builds
//          on it word by word
//   to the end: the lower third holds while the camera keeps a slow push
// The name is the words up to the first comma; the role is the rest, a leading "the" dropped
// and its first letter in capitals.

// Helpers, called directly: 0 to 1 over lengthMs from atMs, held at 1, one per curve,
// since each interpolate names its curve in the call.
function range(fps, atMs, lengthMs) {
  return [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)]
}
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function travel(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}

// Motion blur that follows speed: a move of more than a few pixels a frame softens, and
// only while it is moving. moved is how far the element travelled since the last frame.
function blurFor(moved, unit) {
  const px = Math.min(8, Math.abs(moved) / (6 * unit)) * unit
  return px > 0.4 * unit ? 'blur(' + px.toFixed(2) + 'px)' : 'none'
}

// The name and the role: the name runs to the first word with a comma.
function partsOf(words) {
  const comma = words.findIndex((word) => /,$/.test(word.text))
  const end = comma >= 0 ? comma : 1
  const name = words.slice(0, end + 1)
  // A role read as "the chief financial officer" is set without its "the", as a title is.
  const rest = words.slice(end + 1)
  const role = rest.length > 1 && /^the$/i.test(rest[0].text) ? rest.slice(1) : rest
  return {
    nameAt: name.length > 0 ? name[0].atMs : 0,
    name: name.map((word) => word.text).join(' ').replace(/,$/, ''),
    role: role.map((word, index) => ({
      atMs: word.atMs,
      text: (index === 0 ? word.text.charAt(0).toUpperCase() + word.text.slice(1) : word.text).replace(/[.]$/, ''),
    })),
  }
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors, fonts } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080

  const parts = React.useMemo(() => partsOf(props.words), [props.words])
  const roleAt = parts.role.length > 0 ? parts.role[0].atMs : props.durationMs
  const nameSize = (portrait ? 84 : 92) * unit
  const roleSize = (portrait ? 44 : 46) * unit
  const room = width - inset.left - inset.right
  const nameW = Math.min(room - 60 * unit, parts.name.length * 0.56 * nameSize)
  const roleW = Math.min(room - 60 * unit, parts.role.map((word) => word.text).join(' ').length * 0.52 * roleSize)
  const bandW = Math.max(nameW, roleW) + 80 * unit

  // The bar stands up first; the name slides out from behind it; the band widens for the role.
  const bar = arrive(frame, fps, 0, motion.ms.enter)
  const out = arrive(frame, fps, parts.nameAt, motion.ms.reveal)
  const outBefore = arrive(frame - 1, fps, parts.nameAt, motion.ms.reveal)
  const band = travel(frame, fps, roleAt - motion.ms.micro, motion.ms.move)
  const push = travel(frame, fps, 0, props.durationMs)
  const barH = nameSize * 1.1 + 18 * unit + (roleSize * 1.3 + 14 * unit) * band

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        justifyContent: 'flex-end', alignItems: 'flex-start',
        transform: 'scale(' + (1 + 0.02 * push) + ')', transformOrigin: inset.left + 'px 100%',
      }}
    >
      <div style={{ position: 'relative', display: 'flex', alignItems: 'stretch', marginBottom: 24 * unit }}>
        <div
          style={{
            width: 12 * unit, height: barH, backgroundColor: colors.accent, alignSelf: 'flex-end',
            transform: 'scaleY(' + bar + ')', transformOrigin: 'bottom',
          }}
        />
        <div
          style={{
            position: 'relative', width: bandW, paddingLeft: 32 * unit, paddingTop: 10 * unit, paddingBottom: 10 * unit,
            clipPath: 'inset(-20% -20% -20% 0)',
            // The band's surface widens out from the bar as the role begins.
            backgroundImage: 'linear-gradient(' + Remotion.withAlpha(colors.surface, 0.92) + ', ' + Remotion.withAlpha(colors.surface, 0.92) + ')',
            backgroundRepeat: 'no-repeat', backgroundSize: band * 100 + '% 100%',
          }}
        >
          <div
            style={{
              fontFamily: fonts.heading, fontSize: nameSize, lineHeight: 1.1, color: colors.textPrimary, whiteSpace: 'nowrap',
              transform: 'translateX(' + (out - 1) * (nameW + 40 * unit) + 'px)',
              filter: blurFor((out - outBefore) * (nameW + 40 * unit), unit),
            }}
          >
            {parts.name}
          </div>
          <div style={{ fontFamily: fonts.title, fontSize: roleSize, lineHeight: 1.3, color: colors.textSecondary, marginTop: 14 * unit * band, height: roleSize * 1.3 * band, overflow: 'hidden', whiteSpace: 'nowrap' }}>
            {parts.role.map((word) => {
              const enter = arrive(frame, fps, word.atMs, motion.ms.enter)
              return (
                <span key={word.atMs} style={{ display: 'inline-block', marginRight: '0.25em', opacity: enter, transform: 'translateY(' + (1 - enter) * motion.px.rise * unit + 'px)' }}>
                  {word.text}
                </span>
              )
            })}
          </div>
        </div>
      </div>
    </Remotion.AbsoluteFill>
  )
}

````
